<?php
namespace Delnavazan\Platform\Admin\Controller;

use Delnavazan\Platform\Core\Application\TeacherAvailabilityService;
use Delnavazan\Platform\Core\Application\BookingAvailabilityPolicy;
use Delnavazan\Platform\Core\Infrastructure\Repository\TeacherAvailabilityRepository;

/** Protected management surface for Core availability facts only. */
final class TeacherAvailabilityController {
    public static function handlePost(): void {
        if ( ( $_SERVER['REQUEST_METHOD'] ?? '' ) !== 'POST' ) return;
        if ( ! current_user_can( 'dzn_manage_teacher_availability' ) ) wp_die( 'Access denied.', 'Delnavazan', array( 'response' => 403 ) );
        $post = wp_unslash( $_POST ); $action = sanitize_key( $post['dzn_action'] ?? '' );
        if ( ! in_array( $action, array( 'set_availability_profile', 'set_availability_rule', 'set_availability_exception', 'set_booking_availability_policy' ), true ) ) return;
        check_admin_referer( 'dzn_platform_' . $action );
        try { $service = new TeacherAvailabilityService(); match ( $action ) { 'set_availability_profile' => $service->setProfile( $post ), 'set_availability_rule' => $service->setRecurringRule( $post ), 'set_availability_exception' => $service->setDatedException( $post ), 'set_booking_availability_policy' => BookingAvailabilityPolicy::update( $post )['version'] }; self::redirect( 'Saved. Availability settings have been updated.' ); } catch ( \Throwable ) { self::redirect( 'Operation failed; no change was saved.', true ); }
    }
    public static function screen(): void {
        if ( ! current_user_can( 'dzn_manage_teacher_availability' ) ) { echo '<div class="wrap"><p>Access denied.</p></div>'; return; }
        $repo = new TeacherAvailabilityRepository(); echo '<div class="wrap"><h1>Teacher availability</h1><p>Core local-wall-clock facts only. They do not use Amelia, Google Calendar, profiles, or historical bookings.</p>'; self::messages(); $policy = BookingAvailabilityPolicy::current(); echo '<h2>Academy booking availability policy</h2><p>Global introductory-booking policy applied above all Teacher availability. Quiet hours may cross midnight.</p>'; self::form( 'set_booking_availability_policy', 'Academy quiet hours and candidate interval', array( array( 'academy_timezone', 'Academy IANA timezone', $policy['academy_timezone'] ), array( 'quiet_start', 'Academy quiet hours start: HH:MM:SS', $policy['quiet_start'] ), array( 'quiet_end', 'Academy quiet hours end: HH:MM:SS', $policy['quiet_end'] ), array( 'student_quiet_start', 'Student local quiet hours start: HH:MM:SS', $policy['student_quiet_start'] ), array( 'student_quiet_end', 'Student local quiet hours end: HH:MM:SS', $policy['student_quiet_end'] ), array( 'candidate_interval_minutes', 'Candidate interval minutes', (string) $policy['candidate_interval_minutes'] ) ) ); self::form( 'set_availability_profile', 'Teacher timezone profile', array( array( 'teacher_id', 'Teacher' ), array( 'timezone', 'IANA timezone (for example, Australia/Brisbane)' ), array( 'status', 'Profile status' ) ) ); self::table( 'Availability profiles', $repo->rows( 'teacher_availability_profiles' ) ); self::form( 'set_availability_rule', 'Recurring weekly rule', array( array( 'teacher_id', 'Teacher' ), array( 'weekday', 'Day of week' ), array( 'local_start_time', 'Local start time' ), array( 'local_end_time', 'Local end time' ), array( 'state', 'Availability' ), array( 'timezone', 'Teacher local time zone' ), array( 'status', 'Rule status' ) ) ); echo '<p class="description">To retire a weekly rule, enter the same Teacher, day, times, availability and time zone, then set Rule status to Inactive.</p>'; self::table( 'Recurring rules', $repo->rows( 'teacher_availability_rules' ) ); self::form( 'set_availability_exception', 'Dated exception', array( array( 'teacher_id', 'Teacher' ), array( 'local_date', 'Date' ), array( 'all_day', 'Apply this availability all day' ), array( 'local_start_time', 'Local start time (leave blank for all day)' ), array( 'local_end_time', 'Local end time (leave blank for all day)' ), array( 'state', 'Availability' ), array( 'timezone', 'Teacher local time zone' ), array( 'status', 'Exception status' ) ) ); echo '<p class="description">To retire an exception, enter the same Teacher, date, availability and time zone, then set Exception status to Inactive.</p>'; self::table( 'Dated exceptions', $repo->rows( 'teacher_availability_exceptions' ) ); echo '</div>';
    }
    private static function form(string $action, string $title, array $fields): void { $teacherId=self::contextId('teacher_id'); echo '<h2>' . esc_html( $title ) . '</h2><form method="post">'; wp_nonce_field( 'dzn_platform_' . $action ); echo '<input type="hidden" name="dzn_action" value="' . esc_attr( $action ) . '">'; foreach ( $fields as $field ) { $name=$field[0]; $label=$field[1]; if ($name === 'teacher_id') { self::teacherSelector($teacherId); continue; } if($name==='weekday'){self::choice($name,$label,array('1'=>'Monday','2'=>'Tuesday','3'=>'Wednesday','4'=>'Thursday','5'=>'Friday','6'=>'Saturday','7'=>'Sunday'),'1');continue;} if($name==='state'){self::choice($name,$label,array('preferred'=>'Prefer this time','requestable'=>'Available on request','blocked'=>'Unavailable'),'requestable');continue;} if($name==='status'){self::choice($name,$label,array('active'=>'Active','inactive'=>'Inactive'),'active');continue;} if($name==='all_day'){echo '<p><label><input type="checkbox" name="all_day" value="1"> '.esc_html($label).'</label></p>';continue;} $value=$field[2] ?? ''; echo '<p><label>' . esc_html( $label ) . '<br><input class="regular-text" name="' . esc_attr( $name ) . '" value="' . esc_attr( (string) $value ) . '"></label></p>'; } submit_button( 'Save' ); echo '</form>'; }
    private static function teacherSelector(string $selected): void { $options=(new \Delnavazan\Platform\Core\Application\CoreReadService())->teacherOptionsForAvailability(); echo '<p><label>Teacher<br><select required name="teacher_id"><option value="">Choose a teacher</option>'; foreach ($options as $row) { $label=(string)($row->display_name?:$row->english_name?:$row->persian_name?:'Teacher'); if($row->status!=='active')$label.=' (inactive)'; echo '<option value="'.esc_attr((string)$row->id).'"'.selected($selected,(string)$row->id,false).'>'.esc_html($label).'</option>'; } echo '</select></label></p>'; }
    private static function contextId(string $key): string { $value=wp_unslash($_GET[$key]??''); return is_scalar($value)&&preg_match('/^[1-9][0-9]*$/D',(string)$value)?(string)absint($value):''; }
    private static function choice(string $name,string $label,array $options,string $selected):void{echo '<p><label>'.esc_html($label).'<br><select name="'.esc_attr($name).'">';foreach($options as$value=>$text)echo '<option value="'.esc_attr((string)$value).'"'.selected($selected,(string)$value,false).'>'.esc_html($text).'</option>';echo '</select></label></p>';}
    private static function table(string $title, array $rows): void { echo '<h3>' . esc_html( $title ) . '</h3>'; if ( ! $rows ) { echo '<p>No records.</p>'; return; } $labels=array('teacher'=>'Teacher','time_zone'=>'Time zone','profile_state'=>'Profile status','day'=>'Day','local_start'=>'From','local_end'=>'To','availability'=>'Availability','rule_state'=>'Rule status','date'=>'Date','coverage'=>'Coverage','exception_state'=>'Exception status'); $fields = array_keys( get_object_vars( $rows[0] ) ); echo '<table class="widefat striped"><thead><tr>'; foreach ( $fields as $field ) echo '<th>' . esc_html( $labels[$field]??ucfirst(str_replace('_',' ',$field)) ) . '</th>'; echo '</tr></thead><tbody>'; foreach ( $rows as $row ) { echo '<tr>'; foreach ( $fields as $field ) { $value = property_exists( $row, $field ) ? $row->{$field} : ''; echo '<td>' . esc_html( (string) $value ) . '</td>'; } echo '</tr>'; } echo '</tbody></table>'; }
    private static function messages(): void { if ( ! isset( $_GET['dzn_notice'] ) ) return; echo '<div class="notice ' . esc_attr( ( ( $_GET['dzn_error'] ?? '' ) === '1' ) ? 'notice-error' : 'notice-success' ) . '">' . esc_html( sanitize_text_field( wp_unslash( $_GET['dzn_notice'] ) ) ) . '</div>'; }
    private static function redirect(string $notice, bool $error = false): never { $url = add_query_arg( array( 'page' => 'dzn-teacher-availability', 'dzn_notice' => $notice, 'dzn_error' => $error ? '1' : '0' ), admin_url( 'admin.php' ) ); nocache_headers(); if ( wp_safe_redirect( $url ) ) exit; wp_die( esc_html( $notice ), 'Delnavazan', array( 'response' => $error ? 500 : 200 ) ); }
}
